import * as React from "react";
import { type VariantProps } from "class-variance-authority";
import { ToggleGroup as ToggleGroupPrimitive } from "radix-ui";

import { SlidingIndicator } from "../lib/sliding-indicator";
import { useMeasuredIndicator } from "../lib/use-measured-indicator";
import { toggleVariants } from "./toggle";

import { cn } from "../lib/utils";

import controlStyles from "./controls.module.css";

const ToggleGroupContext = React.createContext<
  VariantProps<typeof toggleVariants> & {
    spacing?: number;
    orientation?: "horizontal" | "vertical";
  }
>({
  size: "default",
  variant: "outline",
  spacing: 0,
  orientation: "horizontal"
});

function ToggleGroup({
  className,
  variant = "outline",
  size = "default",
  spacing = 0,
  orientation = "horizontal",
  bare = false,
  width = "content",
  children,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<typeof ToggleGroupPrimitive.Root> &
  VariantProps<typeof toggleVariants> & {
    spacing?: number;
    orientation?: "horizontal" | "vertical";
    bare?: boolean;
    width?: "content" | "full";
  } & { ref?: React.Ref<React.ComponentRef<typeof ToggleGroupPrimitive.Root>> }) {
  const list = React.useRef<HTMLDivElement | null>(null);
  const attach = React.useCallback(
    (node: HTMLDivElement | null) => {
      list.current = node;
      if (typeof ref === "function") ref(node);
      else if (ref) ref.current = node;
    },
    [ref]
  );
  const sliding = props.type === "single" && spacing === 0;
  const { state: indicator } = useMeasuredIndicator({
    listRef: list,
    activeSelector: '[data-slot="toggle-group-item"][data-state="on"]',
    itemSelector: '[data-slot="toggle-group-item"]',
    watch: children,
    enabled: sliding
  });
  return (
    <ToggleGroupPrimitive.Root
      ref={attach}
      data-slot="toggle-group"
      data-variant={variant === "default" ? "outline" : variant}
      data-size={size}
      data-spacing={spacing}
      data-bare={bare || undefined}
      data-width={width}
      data-indicator={sliding || undefined}
      orientation={orientation}
      className={cn(controlStyles.toggleGroup, className)}
      {...props}
      style={{ "--cipher-toggle-group-gap": `${spacing * 4}px`, ...props.style } as React.CSSProperties}
    >
      {sliding && <SlidingIndicator state={indicator} className={controlStyles.indicator} />}
      <ToggleGroupContext value={{ variant, size, spacing, orientation }}>
        {children}
      </ToggleGroupContext>
    </ToggleGroupPrimitive.Root>
  );
}
ToggleGroup.displayName = "ToggleGroup";

function ToggleGroupItem({
  className,
  children,
  variant = "outline",
  size = "default",
  ref,
  ...props
}: React.ComponentPropsWithoutRef<typeof ToggleGroupPrimitive.Item> &
  VariantProps<typeof toggleVariants> & {
    ref?: React.Ref<React.ComponentRef<typeof ToggleGroupPrimitive.Item>>;
  }) {
  const context = React.useContext(ToggleGroupContext);
  const { "data-state": _wrapperState, ...itemProps } = props as typeof props & {
    "data-state"?: string;
  };

  return (
    <ToggleGroupPrimitive.Item
      ref={ref}
      data-variant={
        (context.variant || variant) === "default" ? "outline" : context.variant || variant
      }
      data-size={context.size || size}
      data-spacing={context.spacing}
      className={cn(
        toggleVariants({
          variant: context.variant || variant,
          size: context.size || size
        }),
        className
      )}
      {...itemProps}
      data-slot="toggle-group-item"
    >
      <span data-press="">{children}</span>
    </ToggleGroupPrimitive.Item>
  );
}
ToggleGroupItem.displayName = "ToggleGroupItem";

export { ToggleGroup, ToggleGroupItem };
